def wr(p,o):p.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
def ev(k,title,date,at,text,url):return dict(kind=k,title=title,date=date,at=at,text=text,url=url,source=url.split('/')[2])
def sc(title,text,at,z,k,years=None,overlay=False):
 s=dict(title=title,text=text,view=dict(mode='globe',center=at,zoom=z),modernBorders=False,layers=[dict(type='cards',data='events',kinds=k,list=True,year='t')],sources=['editorial'])
 if years:s['timeline']=dict(years=years,start=years[-1])
 if overlay:s['layers'].insert(0,dict(type='overlay',data='atlas',opacity=.9));s['sources'].append('hre-reilly1796')
 return s
def story(id,title,hook,events,scenes,notes):
 kinds={e['kind']:dict(label=e['kind'].replace('_',' ').title(),color='c'+str(i%5+1)) for i,e in enumerate(events)}
 ds=dict(source='editorial',asOf='Historical synthesis; editorial cutoff 2026-10-14',retrieved='2026-10-14',units='Dated events and approximate named-place coordinates in longitude/latitude degrees',note='Original paraphrases linked to institutional histories and primary documents. Markers locate cities or regions, not territorial extent, exact ceremonies or front lines. Years are conventional historical years; dates before 1582 follow the historical Julian calendar unless noted.',kinds=kinds,items=events,places=[dict(at=e['at'],names=[dict(name=e['title'],**{'from':None,'to':None})]) for e in events])
 wr(OUT/(id+'.json'),ds)
 data={'events':'data/history/hre/'+id+'.json'}
 if any('atlas'==l.get('data') for s in scenes for l in s['layers']):data['atlas']='data/history/hre/reilly1796.json'
 if id=='hre-patchwork':
  data['territories']='data/history/hre/territories1789.json'
  outline=sc('An imperial outline, circa 1789','The reconstructed map distinguishes imperial membership from possessions held outside the Empire. This source-derived outline is approximate: it describes the mapmaker’s circa-1789 interpretation, with coarse geographic alignment, rather than surveyed legal boundaries.',[10.5,50.5],6,[])
  outline['layers']=[dict(type='shapes',data='territories',year=1789,groups=['empire'],opacity=.18,inner=False,labels=False)]
  outline['sources']=['hre-alphathon1789']
  units=sc('Dynasties crossed the imperial boundary','The source names Habsburg imperial possessions and Brandenburg separately from those dynasties’ extra-imperial lands. Only the source’s within-empire paths are highlighted. The outer outline supplies context; these are selected holdings, not a complete list of imperial estates.',[12.5,50.5],6,[])
  units['layers']=[dict(type='shapes',data='territories',year=1789,groups=['habsburg','brandenburg'],opacity=.7,inner=False),dict(type='shapes',data='territories',year=1789,groups=['empire'],opacity=.12,inner=False,labels=False)]
  units['sources']=['hre-alphathon1789']
  scenes[2:2]=[outline,units]
  notes+=' Source-derived 1789 outline/selected holdings: Alphathon, revision Fenn-O-maniC, CC BY-SA 3.0; full base-map contributor attribution in data/history/hre/attribution.txt. Approximate projection inversion has mean 44 km/max 100 km coastal-control residual, suitable for overview only; historical border accuracy is not established by this fit. The original upload comment and embedded SVG title say 1789 despite a copied Commons summary saying 1279. '
 st=dict(id=id,cat='People',title=title,hook=hook,updated='2026-10-14',notes=notes+' Coordinates are approximate named-place locators, not imported surveyed points. Modern borders are hidden. Event cards contain claim-level citations. The later term Holy Roman Empire must not be projected unchanged onto Charlemagne’s Frankish realm.',sources=['editorial']+(['hre-reilly1796'] if 'atlas'in data else [])+(['hre-alphathon1789'] if 'territories'in data else []),data=data,scenes=scenes)
 wr(ROOT/'stories'/(id+'.json'),st)
events=[ev('palace','Aachen',800,AC,'Charlemagne made Aachen his preferred residence; the surviving palatine chapel was built around 790–800.',A),ev('coronation','Rome',800,RO,'Pope Leo III crowned Charlemagne emperor in Rome in 800. This marker locates the city, not a surveyed ceremony site.','https://www.habsburger.net/en/glossary/holy-roman-empire'),ev('burial','Aachen: burial',814,AC,'Charlemagne was buried at Aachen in 814.',A),ev('successors','Otto’s Aachen',936,AC,'Otto I was crowned king at Aachen in 936; this was a later Saxon dynasty, not Charlemagne’s own reign.',O)]
story('hre-charlemagne','Charlemagne','A Frankish ruler revived the western imperial title; later emperors inherited its symbolism.',events,[sc('A palace north of the Alps','Aachen was Charlemagne’s preferred residence. Its palatine chapel, begun around 790–800, placed a monumental court church north of the Alps.',AC,9,['palace']),sc('The imperial title at Rome','In 800 Pope Leo III crowned Charlemagne emperor in Rome. Compare Rome with Aachen: the ceremony’s religious authority and the ruler’s favoured residence occupied different places.',[10,47],4,['palace','coronation']),sc('A ruler dies; a place persists','Charlemagne’s burial at Aachen in 814 gave the chapel an enduring dynastic association. The map stays at the same place as the timeline moves beyond his lifetime.',AC,9,['palace','burial'],[800,814]),sc('A later dynasty takes the throne','Otto I’s royal coronation at Aachen in 936 connected a Saxon ruler with a Carolingian site. The Holy Roman Empire’s origins are a process: the 800 revival and Otto’s later empire are distinguished.',AC,8,['successors'])], 'UNESCO Aachen supplies building and burial chronology; Habsburger glossary supplies 800; Met Ottonian Art supplies 936. No map of Charlemagne’s realm is inferred.')
events=[ev('royal','Aachen',936,AC,'Otto I became king at Aachen in 936.',O),ev('imperial','Rome',962,RO,'The pope invested Otto I with the imperial title in 962.',O),ev('saxon','Quedlinburg',1000,[11.15,51.79],'Quedlinburg was a royal centre under the Saxon-Ottonian dynasty (919–1024); 1000 is a period anchor, not a founding date.',Q),ev('church','Hildesheim',1000,[9.95,52.15],'Bishop Bernward’s Hildesheim commissioned major works informed by ancient imperial and Christian monuments. 1000 identifies the cultural period, not a precise commission date.',O)]
story('hre-1000','The empire around 1000','Saxon royal centres and Italian imperial coronation formed a geography spanning the Alps.',events,[sc('Royal authority at Aachen','In 936 Otto became king at Aachen. A long-used ceremonial centre helped connect a new dynasty to earlier imperial memory.',AC,8,['royal']),sc('Imperial authority at Rome','Otto received the imperial title in Rome in 962. Move the timeline: Aachen’s royal anchor remains while the Roman imperial connection enters the map.',[10,47],4,['royal','imperial'],[936,962]),sc('Saxon centres','Quedlinburg belonged to the heartland of Saxon-Ottonian rulership. Around 1000, royal places and religious communities helped sustain government; this city anchor does not define an imperial border.',[11.15,51.79],9,['saxon']),sc('Churches and imperial culture','Hildesheim’s bronze monuments drew on ancient imperial and early Christian models. Compare this ecclesiastical centre with Quedlinburg in the previous scene: churches and royal sites sustained different parts of the northern imperial world.',[9.95,52.15],9,['church'])], 'Met Ottonian Art and UNESCO Quedlinburg. 1000 is a cultural-period snapshot. The map shows cited political/cultural centres, not speculative territory.')
events=[ev('election','Frankfurt',1356,FR,'The Golden Bull required electors to meet at Frankfurt and regulated majority election of a King of the Romans.',G),ev('diet','Regensburg',1663,RE,'Regensburg hosted the Perpetual Imperial Diet from 1663 to 1806.',R),ev('electors','Mainz',1356,[8.27,50.0],'The Archbishop of Mainz was one of the three spiritual electors named in the Golden Bull; the marker locates the city, not his territorial possessions.',G),ev('electors','Trier',1356,[6.64,49.76],'The Archbishop of Trier was a spiritual elector under the Golden Bull; city location does not trace his possessions.',G),ev('electors','Cologne',1356,[6.96,50.94],'The Archbishop of Cologne was a spiritual elector under the Golden Bull; the named see is not mapped as a territorial polygon.',G),ev('atlas','Reilly’s Germany',1796,[10.5,50],'Reilly’s 1796 atlas depicts administrative divisions and hand-coloured territories. Its colouring is historical cartography, not a modern authoritative sovereignty database.',MAP)]
mapnote='Overlay: Reilly/Benedicti, Karte von der Deutschland, Vienna 1796, Rumsey 11151.021. Approximate georeferencing with city/coast controls; retained hand-coloured divisions are the mapmaker’s portrayal, not reconstructed polygons. Credit David Rumsey Map Collection, David Rumsey Map Center, Stanford University Libraries. Adaptation CC BY-NC-SA 3.0. Fine print is supplemented by readable modern annotations; a close view deliberately shows only part of the empire. '
story('hre-patchwork','The territorial patchwork','An elected monarchy joined many territorial authorities through shared institutions.',events,[sc('Election is an institution','The Golden Bull of 1356 specified electors and rules for choosing the King of the Romans. Frankfurt’s meeting role helps explain the empire as a political structure, not simply an emperor’s estate.',FR,9,['election']),sc('A common meeting place','From 1663, the Perpetual Diet sat at Regensburg. A shared assembly operated within an empire whose territorial rulers retained substantial authority.',RE,9,['diet']),sc('A dated patchwork','Reilly’s map of Germany, published in Vienna in 1796, preserves a dense pattern of coloured administrative divisions. This archival portrayal provides the territorial fallback: it is a dated map, with approximate alignment, rather than invented modern polygons.',[10.5,50],6,['atlas'],overlay=True),sc('Look closer, keep the context','The Rhine–Main area shows small divisions packed together. Mainz, Trier and Cologne were the Golden Bull’s spiritual electors; Frankfurt hosted elections. The city markers name institutional centres, not the extent of their lands. This 1796 regional view is later than the 1356 rules.',[7.8,50.25],16,['electors'],overlay=True)],mapnote+'Golden Bull primary text; UNESCO Regensburg. No count of territories or quantified border accuracy is claimed.')
events=[ev('talks','Münster',1648,[7.63,51.96],'The imperial peace with France was concluded at Münster in 1648.',P),ev('talks','Osnabrück',1648,[8.05,52.28],'The imperial peace with Sweden was concluded at Osnabrück in 1648.',P),ev('religion','Imperial religious settlement',1648,[12.10,49.02],'The treaties set a religious and constitutional settlement within the Empire; Regensburg is an institutional locator, not a signing location.',W),ev('continuity','Regensburg’s continuing Diet',1663,RE,'The Perpetual Diet began in 1663, demonstrating imperial institutions continued after the peace.',R)]
story('hre-westphalia','Westphalia','Two treaty cities ended the Thirty Years’ War; imperial institutions continued afterwards.',events,[sc('Two cities, related negotiations','Münster and Osnabrück hosted the peace settlements with France and Sweden in 1648. Their proximity makes Westphalia a concrete diplomatic geography, not the name of a single signing table.',[7.85,52.12],24,['talks']),sc('Religion and imperial law','The treaties addressed confessional rights and relations among imperial estates. The institutional anchor at Regensburg locates the empire’s assembly world; it does not mark where the treaties were signed.',[10,51],6,['talks','religion']),sc('Peace did not dissolve the empire','Regensburg’s Perpetual Diet began in 1663 and continued until 1806. Moving beyond 1648 makes the continuing institutional geography visible.',RE,9,['religion','continuity'],[1648,1663]),sc('A much later territorial view','The 1796 Reilly map shows the empire’s territorial complexity long after Westphalia. It is expressly not a map of the 1648 settlement and cannot be used to read off its immediate border changes.',[10.5,50],6,[],overlay=True)],mapnote+'Westphalia primary treaty text and Habsburger peace history; UNESCO Regensburg. Calendar note: the primary treaties are dated 14/24 October 1648 (Julian/Gregorian); scene years avoid silently selecting one day style.')
events=[ev('recess','Regensburg',1803,RE,'The 1803 Final Recess reorganised the empire, secularising ecclesiastical territories and mediatising many imperial cities. Regensburg locates its institutional setting.',E),ev('austria','Vienna',1804,VI,'Francis assumed the title of Emperor of Austria in 1804, while still holding the older imperial office.','https://www.habsburger.net/en/chapter/house-austria-habsburgs-and-empire'),ev('rhine','Rhine Confederation',1806,[8.5,49.5],'The formation of a separate union of Rhenish states was cited in Francis’s declaration ending his imperial office. This regional anchor is not a boundary or treaty-signing site.',D),ev('abdication','Vienna',1806,VI,'On 6 August 1806 Francis II laid down the imperial crown and released imperial estates and servants from their obligations.',D)]
story('hre-end','Napoleon and the end','Reorganisation, a rival imperial title and the Rhine Confederation preceded the abdication.',events,[sc('Reorganisation from within','The Final Recess of 1803 secularised church territories and reduced the number of independent imperial cities. Regensburg anchors the empire’s institutional setting; no speculative before-and-after borders are drawn.',RE,9,['recess']),sc('Two imperial titles','In 1804 Francis adopted an Austrian imperial title while still Holy Roman Emperor. Vienna’s court therefore links two different offices, rather than a simple renaming of the same state.',VI,8,['austria']),sc('Napoleon’s new political order','The Rhine Confederation separated participating states from the imperial structure in 1806. The regional locator deliberately avoids drawing an uncited outline of its membership.',[8.5,49.5],7,['rhine']),sc('An office is relinquished','Francis’s declaration of 6 August 1806, issued at Vienna, laid down the imperial crown and released estates and servants from their obligations. The sequence ends with a primary document, not an invented map of a final front line.',[13,49],9,['recess','austria','rhine','abdication'],[1803,1804,1806])], 'GHDI introduction for 1803, Habsburger House of Austria for 1804, primary abdication declaration for 1806. Napoleon’s pressure is explained through the Rhine union cited in the declaration; markers are political locators, not military movements. The declaration date uses Gregorian calendar.')
events=[ev('congress','Vienna',1815,VI,'The Congress of Vienna established the German Confederation within a wider European settlement.',V),ev('assembly','Frankfurt',1815,FR,'The German Federal Act of 8 June 1815 designated Frankfurt as the seat of the federal assembly.',F),ev('cities','Hamburg',1815,[9.99,53.55],'Hamburg was one of the four free cities joining the 1815 Confederation.',F),ev('cities','Bremen',1815,[8.80,53.08],'Bremen was another of the four free cities joining the 1815 Confederation.',F),ev('heritage','Aachen’s surviving chapel',2026,AC,'Aachen’s Carolingian chapel survives within a cathedral enlarged by later generations.',A),ev('heritage','Regensburg’s old town',2026,RE,'Regensburg preserves buildings linked to its imperial assembly and medieval trading history.',R)]
story('hre-after','What followed','The German Confederation created a new federal order; imperial places outlived the institution.',events,[sc('A settlement in Vienna','In 1815 the Congress of Vienna created the German Confederation. It followed the dissolved empire but did not restore its imperial crown.',VI,8,['congress']),sc('The assembly moves to Frankfurt','The 1815 Federal Act placed the confederal assembly at Frankfurt. Comparing Vienna with Frankfurt separates the diplomatic settlement from the new institution’s meeting place.',[12,49],5,['congress','assembly']),sc('Free cities in the new order','The Federal Act lists Lübeck, Frankfurt, Bremen and Hamburg alongside member states. The northern city anchors show continuity of some urban political identities within a different federal arrangement.',[9.5,53.4],24,['cities']),sc('Buildings after institutions','Aachen’s chapel and Regensburg’s old town preserve traces of earlier imperial life. These present-day heritage sites are not evidence that the empire’s political authority survives.',[9,50],6,['heritage'])], 'GHDI German Federal Act (1815) for Frankfurt and the named free cities; Habsburger Congress of Vienna history for the new order; UNESCO Aachen and Regensburg for surviving heritage. Heritage locators are reviewed at cutoff, not a claim of current territorial sovereignty.')
