if '--overlay' in sys.argv:
 import numpy as np,hashlib,urllib.request
 from PIL import Image
 cache=ROOT/'.cache/roadmap-review/M8';cache.mkdir(parents=True,exist_ok=True)
 url='https://www.davidrumsey.com/rumsey/download.pl?image=/162/11151021.jp2'
 path=cache/'reilly1796.jp2'
 if not path.exists():urllib.request.urlretrieve(url,path)
 expected='2c7bad5e0f9566d1fefaf283a321b3c459b3de014c6fe5ac80728756e69801bb'
 if hashlib.sha256(path.read_bytes()).hexdigest()!=expected:raise ValueError('Archive source changed; re-audit before rebuilding')
 # Hand-selected coastal/city anchors in the 1800px preview; approximate, not survey controls.
 anchors=[('Texel',656,377,4.80,53.05),('Helgoland',895,228,7.89,54.18),('Ruegen',1180,138,13.4,54.42),('Gdansk',1530,188,18.65,54.35),('Strasbourg',759,855,7.75,48.58),('Basel',749,949,7.59,47.56),('Lake Constance',927,973,9.4,47.6),('Venice',1126,1090,12.34,45.44),('Trieste',1236,1059,13.77,45.65)]
 im=Image.open(path).convert('RGBA');scale=im.width/1800
 g=np.array([[x*scale,y*scale,lon,lat] for name,x,y,lon,lat in anchors])
 def terms(x,y):return np.stack([np.ones_like(x),x,y,x*x,x*y,y*y],axis=-1)
 a=terms(g[:,2],g[:,3]);cx=np.linalg.lstsq(a,g[:,0],rcond=None)[0];cy=np.linalg.lstsq(a,g[:,1],rcond=None)[0];err=np.hypot(a@cx-g[:,0],a@cy-g[:,1])
 # One global high-resolution patch supports both overview and a Rhine–Main close view.
 bbox=[3,44.5,21,55.5];width=2400;height=round(width*11/18)
 x,y=np.meshgrid(np.linspace(3,21,width),np.linspace(55.5,44.5,height));t=terms(x,y);px=t@cx;py=t@cy
 xi=np.rint(px).astype(int);yi=np.rint(py).astype(int);src=np.asarray(im)
 inside=(xi>=415*scale)&(xi<=1640*scale)&(yi>=115*scale)&(yi<=1105*scale)
 arr=src[np.clip(yi,0,im.height-1),np.clip(xi,0,im.width-1)].copy();arr[~inside]=0
 Image.fromarray(arr).save(OUT/'reilly1796.webp',quality=53)
 meta=dict(source='hre-reilly1796',units='Historical cartographic image; not measured territorial area',asOf='Map published 1796; historical cartographic portrayal',retrieved='2026-10-14',title='Reilly 1796: territorial divisions (approximate alignment)',image='data/history/hre/reilly1796.webp',bbox=bbox,url=MAP,download=url,sha256=hashlib.sha256(path.read_bytes()).hexdigest(),licence='CC BY-NC-SA 3.0',credit='David Rumsey Map Collection, David Rumsey Map Center, Stanford University Libraries',note='Main map panel cropped; retained original hand colouring and names. Second-order inverse warp with nine approximate named-place/coast controls. This is cartographic interpretation, not exact sovereignty geometry. Fit residual measures control consistency only, not historical border accuracy. Close view retains only a regional part of the map.',gcps=[dict(name=n,pixel=[x*scale,y*scale],at=[lon,lat],residualPx=round(float(e),1)) for (n,x,y,lon,lat),e in zip(anchors,err)],fit=dict(order=2,gcps=9,meanErrorPx=round(float(err.mean()),1),maxErrorPx=round(float(err.max()),1)))
 wr(OUT/'reilly1796.json',meta);print(meta['fit'],'image bytes',(OUT/'reilly1796.webp').stat().st_size)
